    maybe_old_commit: Option<&Commit>,
    new_commit: &Commit,
) -> Result<(), CommandError> {
    assert!(self.may_update_working_copy);
    let stats = update_working_copy(
        &self.user_repo.repo,
        &mut self.workspace,
        maybe_old_commit,
        new_commit,

