        GitFetchRefExpression {
            bookmark: StringExpression::all(),
            tag: StringExpression::none(),
        },
    )?;
    let git_settings = GitSettings::from_settings(&eng.settings)?;
    let import_options = eng.import_options()?;
    let mut tx = eng.start_tx();
    let mut fetch = GitFetch::new(
        tx.repo_mut(),
        git_settings.to_subprocess_options(),
        &import_options,
    )?;
    fetch.fetch(remote, expanded, &mut engine::DebugCallback, None, None)?;
    let stats = fetch.import_refs().block_on()?;
    drop(fetch);
    let lines: Vec<String> = stats
        .changed_remote_bookmarks
        .iter()
        .map(|(symbol, _)| format!("bookmark {symbol} updated"))
        .collect();
    if !tx.repo().has_changes() {
        return Ok(lines);
    }
    tx.repo_mut().rebase_descendants().block_on()?;
    eng.finish_tx(tx, &format!("fetch from git remote {}", remote.as_str()))?;
    Ok(lines)
}

