229	/// True when `revset` references a working copy, so the query must
230	/// go through the spawned CLI's auto-snapshot until the mutation
231	/// lift moves snapshotting in-process.
232	///
233	/// A `@` is working-copy syntax (`@`, `@-`, `ws@`) unless it has
234	/// symbol characters on *both* sides, which is the remote-bookmark
235	/// form (`name@remote`).
236	fn references_working_copy(revset: &str) -> bool {
237	    let is_symbol_char =
238	        |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '/' | '+');
239	    let chars: Vec<char> = revset.chars().collect();
240	    chars.iter().enumerate().any(|(i, &c)| {
241	        c == '@'
242	            && !(i > 0
243	                && is_symbol_char(chars[i - 1])
244	                && chars.get(i + 1).copied().is_some_and(is_symbol_char))
245	    })
246	}
