249	/// return its stdout (`run` trims surrounding whitespace): the
250	/// spawn path for working-copy-relative revsets.
251	fn log_spawn(repo: &Path, rev: &str, template: &str) -> Result<String> {
252	    common::run(
253	        "jj",
254	        &[
255	            "log",
256	            "-r",
257	            rev,
258	            "--no-graph",
259	            "-T",
260	            template,
