268	/// Resolve `revset` in-process and return its commits, in revset
269	/// order (newest first, matching `jj log`).
270	fn commits_of(repo: &Path, revset: &str) -> Result<Vec<Commit>> {
271	    let (workspace, repo_at_head) = common::load_repo(repo)?;
272	    let ids = common::resolve_revset(&workspace, &repo_at_head, revset)?;
273	    ids.iter()
274	        .map(|id| Ok(repo_at_head.store().get_commit(id)?))
275	        .collect()
