278	/// True when `revset` matches at least one commit in `repo`.
279	///
280	/// A valid-but-empty revset (e.g. `conflicts()` on a clean repo)
281	/// is `Ok(false)`; an unresolvable revision is an `Err`, which
282	/// `rev_exists` folds to `false`.
283	pub fn matches(repo: &Path, revset: &str) -> Result<bool> {
284	    if references_working_copy(revset) {
285	        return Ok(!log_spawn(repo, revset, "\"x\"")?.is_empty());
286	    }
287	    let (workspace, repo_at_head) = common::load_repo(repo)?;
288	    Ok(!common::resolve_revset(&workspace, &repo_at_head, revset)?.is_empty())
289	}
