291	/// True when `rev` resolves in `repo`.
292	///
293	/// Folds jj's unresolvable-revision error (`is_no_such_revision`,
294	/// either path) to `Ok(false)`; other failures (bad repo path,
295	/// spawn error) stay `Err`.
296	pub fn rev_exists(repo: &Path, rev: &str) -> Result<bool> {
