1	//! In-process jj mutation engine.
2	//!
3	//! The plumbing jj's own CLI wraps around every mutation
4	//! (`WorkspaceCommandHelper` in jj-cli), reduced to what the facade's
5	//! verbs need: user-config-backed settings, the working-copy snapshot
6	//! cycle, and transaction finish. The reference implementation is jj
7	//! 0.43's `cli_util.rs`; deviations are documented on each function.
8	//!
9	//! - `Engine::open`: settings + workspace + repo-at-head, colocation
10	//!   detected.
11	//! - `Engine::snapshot`: the CLI's `maybe_snapshot`: git head/refs
12	//!   import around a working-copy snapshot, under the same lock file
13	//!   the CLI takes.
14	//! - `Engine::finish_tx`: the CLI's `finish_transaction`: git HEAD
15	//!   reset + ref export, op-store commit, working-copy update.
16	
17	use std::collections::HashMap;
18	use std::path::{Path, PathBuf};
19	use std::sync::Arc;
20	
21	use jj_lib::commit::Commit;
22	use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
23	use jj_lib::fileset::{self, FilesetDiagnostics, FilesetParseContext};
24	use jj_lib::git::{self, GitImportOptions, GitSettings};
25	use jj_lib::gitignore::GitIgnoreFile;
26	use jj_lib::lock::FileLock;
27	use jj_lib::matchers::NothingMatcher;
28	use jj_lib::repo::{ReadonlyRepo, Repo, StoreFactories};
29	use jj_lib::repo_path::{RepoPath, RepoPathUiConverter};
30	use jj_lib::settings::{HumanByteSize, UserSettings};
31	use jj_lib::transaction::Transaction;
32	use jj_lib::working_copy::{SnapshotOptions, WorkingCopyFreshness};
33	use jj_lib::workspace::{Workspace, default_working_copy_factories};
34	use log::debug;
35	use pollster::FutureExt;
36	
37	/// Crate-standard boxed-error result, aliased locally for brevity.
38	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
39	
40	/// One repo opened for mutation: workspace, repo at head, settings,
41	/// and whether the workspace is colocated with git.
42	pub struct Engine {
43	    /// The loaded workspace (owns the working copy).
44	    pub workspace: Workspace,
45	    /// The repo, loaded at (or advanced past) the op-store head.
46	    pub repo: Arc<ReadonlyRepo>,
47	    /// Settings from the user's real jj config (see `stacked_config`).
48	    pub settings: UserSettings,
49	    /// True when `.git` and the working copy are shared with git, so
50	    /// mutations must import from and export to the git side.
51	    pub colocated: bool,
52	}
53	
54	/// Load the user's jj configuration the way the jj CLI does.
55	///
56	/// Layers, lowest to highest: jj-lib defaults, `/etc/jj` (unix),
57	/// `$JJ_CONFIG` (overrides system and user paths) or the user files
58	/// (`~/.jjconfig.toml`, `<config dir>/jj/config.toml` + `conf.d`),
59	/// the repo config (`.jj/repo/config.toml`), then `JJ_USER` /
60	/// `JJ_EMAIL` overrides. Deviation from the CLI: no command-line
61	/// layer and no `EnvBase` layer (debug / color / pager knobs that
62	/// only affect CLI presentation).
63	fn stacked_config(repo_config_path: Option<&Path>) -> Result<StackedConfig> {
64	    let mut config = StackedConfig::with_defaults();
65	    // Keys the engine reads whose defaults ship with the jj CLI's
66	    // config files rather than jj-lib's (values match jj 0.43).
67	    config.add_layer(ConfigLayer::parse(
68	        ConfigSource::Default,
69	        r#"
70	        [snapshot]
71	        auto-track = "all()"
72	        max-new-file-size = "1MiB"
73	        [git]
74	        auto-local-bookmark = false
75	        "#,
76	    )?);
77	    let jj_config = std::env::var("JJ_CONFIG").ok();
78	
79	    if jj_config.is_none() && cfg!(unix) {
80	        load_file_if_exists(&mut config, ConfigSource::System, "/etc/jj/config.toml")?;
81	        load_dir_if_exists(&mut config, ConfigSource::System, "/etc/jj/conf.d")?;
82	    }
83	
84	    if let Some(paths) = &jj_config {
85	        for path in std::env::split_paths(paths).filter(|p| !p.as_os_str().is_empty()) {
86	            if path.is_dir() {
87	                config.load_dir(ConfigSource::User, path)?;
88	            } else {
89	                config.load_file(ConfigSource::User, path)?;
90	            }
91	        }
92	    } else {
93	        let home = std::env::var_os("HOME").map(PathBuf::from);
94	        let config_dir = match std::env::var_os("XDG_CONFIG_HOME") {
95	            Some(x) if !x.is_empty() => Some(PathBuf::from(x)),
96	            _ => home.as_ref().map(|h| h.join(".config")),
97	        };
98	        if let Some(home) = &home {
99	            load_file_if_exists(&mut config, ConfigSource::User, home.join(".jjconfig.toml"))?;
100	        }
101	        if let Some(dir) = &config_dir {
102	            load_file_if_exists(&mut config, ConfigSource::User, dir.join("jj/config.toml"))?;
103	            load_dir_if_exists(&mut config, ConfigSource::User, dir.join("jj/conf.d"))?;
104	        }
105	    }
106	
107	    if let Some(repo_path) = repo_config_path {
108	        load_file_if_exists(
109	            &mut config,
110	            ConfigSource::Repo,
111	            repo_path.join("config.toml"),
112	        )?;
113	    }
114	
115	    let mut env = ConfigLayer::empty(ConfigSource::EnvOverrides);
116	    if let Ok(value) = std::env::var("JJ_USER") {
117	        env.set_value("user.name", value)?;
118	    }
119	    if let Ok(value) = std::env::var("JJ_EMAIL") {
120	        env.set_value("user.email", value)?;
121	    }
122	    if !env.is_empty() {
123	        config.add_layer(env);
124	    }
125	    Ok(config)
