40	/// Crate-standard boxed-error result, aliased locally for brevity.
41	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
42	
43	/// `desc` with the trailing newline jj normalizes descriptions to.
44	fn complete_newline(desc: &str) -> String {
45	    if desc.is_empty() || desc.ends_with('\n') {
46	        desc.to_string()
47	    } else {
48	        format!("{desc}\n")
49	    }
50	}
51	
52	/// Snapshot the working copy, then update the wc commit's
53	/// description and start a new empty change on top (`jj commit`).
54	pub fn commit(repo: &Path, desc: &str) -> Result<()> {
55	    let mut eng = engine::Engine::open(repo)?;
56	    eng.snapshot()?;
57	    let wc_commit = eng.wc_commit()?;
58	    let name = eng.workspace.workspace_name().to_owned();
59	    let mut tx = eng.start_tx();
60	    let new_commit = tx
61	        .repo_mut()
62	        .rewrite_commit(&wc_commit)
63	        .set_description(complete_newline(desc))
64	        .write()
65	        .block_on()?;
66	    let new_wc_commit = tx
67	        .repo_mut()
68	        .new_commit(vec![new_commit.id().clone()], wc_commit.tree())
69	        .write()
70	        .block_on()?;
71	    tx.repo_mut().edit(name, &new_wc_commit).block_on()?;
72	    eng.finish_tx(tx, &format!("commit {}", wc_commit.id().hex()))
73	}
74	
75	/// Snapshot, then rewrite `rev`'s description and rebase its
76	/// descendants (`jj describe -r <rev> -m <desc>`).
77	pub fn describe(repo: &Path, rev: &str, desc: &str) -> Result<()> {
78	    let mut eng = engine::Engine::open(repo)?;
79	    eng.snapshot()?;
80	    let commit = one_commit(&eng, rev)?;
81	    let desc = complete_newline(desc);
82	    if commit.description() == desc {
83	        return Ok(());
84	    }
85	    let mut tx = eng.start_tx();
86	    tx.repo_mut()
87	        .rewrite_commit(&commit)
88	        .set_description(desc)
89	        .write()
90	        .block_on()?;
91	    tx.repo_mut().rebase_descendants().block_on()?;
92	    eng.finish_tx(tx, &format!("describe commit {}", commit.id().hex()))
93	}
