97	pub fn bookmark_set(repo: &Path, name: &str, rev: &str) -> Result<()> {
98	    use jj_lib::op_store::RefTarget;
99	    let mut eng = engine::Engine::open(repo)?;
100	    eng.snapshot()?;
101	    let commit = one_commit(&eng, rev)?;
