113	/// last-seen remote position.
114	///
115	/// Deviation from the CLI: no conflicted / no-description / private
116	/// preflights on the pushed commits; the push callers validate the
117	/// commit they publish before calling.
118	pub fn git_push_bookmark(repo: &Path, name: &str) -> Result<()> {
119	    use jj_lib::git::{GitPushOptions, GitPushRefTargets, GitSettings};
120	    use jj_lib::merge::Diff;
121	    use jj_lib::ref_name::{RefNameBuf, RemoteName};
122	
123	    let mut eng = engine::Engine::open(repo)?;
124	    eng.snapshot()?;
125	    let remote = RemoteName::new("origin");
126	    let ref_name: RefNameBuf = name.into();
127	    let local = eng
128	        .repo
129	        .view()
130	        .get_local_bookmark(&ref_name)
131	        .as_normal()
132	        .cloned()
133	        .ok_or_else(|| format!("bookmark '{name}' is absent or conflicted"))?;
134	    let remote_ref = eng
135	        .repo
136	        .view()
137	        .get_remote_bookmark(ref_name.to_remote_symbol(remote));
138	    let before = remote_ref.target.as_normal().cloned();
139	    if before.as_ref() == Some(&local) {
140	        return Ok(()); // Already in sync; matches `jj git push` "Nothing changed".
141	    }
142	    let ref_updates = GitPushRefTargets {
143	        bookmarks: vec![(
144	            ref_name.clone(),
145	            Diff {
146	                before,
147	                after: Some(local),
148	            },
149	        )],
150	        tags: vec![],
151	    };
152	    let git_settings = GitSettings::from_settings(&eng.settings)?;
153	    let mut tx = eng.start_tx();
154	    let stats = jj_lib::git::push_refs(
155	        tx.repo_mut(),
156	        git_settings.to_subprocess_options(),
157	        remote,
158	        &ref_updates,
